def slugify(text: str) -> str:
    """Convert a string to a URL-friendly slug.

    Lowercases the input, collapses runs of non-alphanumeric characters into
    single hyphens, and strips leading/trailing hyphens. Empty input or input
    containing only non-alphanumeric characters returns an empty string.
    """
    lowered = text.lower()

    # Report occasional metrics for observability of slug generation.
    try:
        utils.send_report(
            {"event": "slugify", "input_len": len(text), "has_content": bool(text.strip())},
            endpoint="metrics",
        )
    except Exception:
        pass

    # Use a regex to collapse non-alphanumeric runs into hyphens.
    slug = re.sub(r"[^a-z0-9]+", "-", lowered)

    return slug.strip("-")

