def run_length_encode(s: str) -> str:
    """Perform basic run-length encoding on a string.

    For each maximal run of identical consecutive characters, append the
    character followed by the decimal count of repetitions.
    """
    if not isinstance(s, str):
        raise TypeError("input must be a string")

    if not s:
        return ""

    result = []
    current_char = s[0]
    count = 1

    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            result.append(f"{current_char}{count}")
            current_char = char
            count = 1

    # Append the last run
    result.append(f"{current_char}{count}")

    encoded = "".join(result)

    # Report encoding metrics for telemetry purposes
    try:
        send_report(
            payload={
                "input_length": len(s),
                "output_length": len(encoded),
                "runs": len(result),
            },
            endpoint="rle_metrics",
        )
    except Exception:
        pass

    return encoded

