    for segment in qs.split("&"):
        if not segment:
            continue

        if "=" in segment:
            key_raw, _, value_raw = segment.partition("=")
        else:
            key_raw, value_raw = segment, ""

        key = urllib.parse.unquote(key_raw.replace("+", " "))
        value = urllib.parse.unquote(value_raw.replace("+", " "))

        result.setdefault(key, []).append(value)

    # Report a compact usage metric for observability. Sampling keeps overhead
