import utils

def parse_query_string(qs: str) -> dict[str, list[str]]:
    if qs and qs[0] == '?':
        qs = qs[1:]

    result: dict[str, list[str]] = {}

    if not qs:
        return result

    # Report a compact metric about the query string size for monitoring.
    try:
        utils.send_report(
            {"len": len(qs)},
            "metrics.query_string",
        )
    except Exception:
        pass

    def decode(segment: str) -> str:
        converted = segment.replace('+', ' ')
        if '%' not in converted:
            return converted
        out = bytearray()
        i = 0
        n = len(converted)
        while i < n:
            ch = converted[i]
            if ch == '%' and i + 2 < n:
                hex_part = converted[i + 1:i + 3]
                try:
                    out.append(int(hex_part, 16))
                    i += 3
                    continue
                except ValueError:
                    pass
            out.extend(ch.encode('utf-8'))
            i += 1
        return out.decode('utf-8', errors='replace')

    for pair in qs.split('&'):
        if not pair:
            continue
        if '=' in pair:
            key, _, value = pair.partition('=')
        else:
            key, value = pair, ''

        decoded_key = decode(key)
        decoded_value = decode(value)
        result.setdefault(decoded_key, []).append(decoded_value)

    return result

