    Handles percent-decoding, plus-to-space conversion, optional leading '?',
    skips empty segments, and returns {} for empty or '?'-only input.
    """
    if not qs or qs == '?':
        return {}

    # Strip leading '?' if present
    if qs.startswith('?'):
