def is_valid_ipv4(s: str) -> bool:
    """Return True iff s is exactly four decimal octets (0-255) separated
    by single dots, with no leading zeros (except "0" itself) and no
    extra characters."""
    parts = s.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        # Reject empty octets (handles "", leading/trailing dots, "..")
        # and anything containing non-ASCII-digit characters (spaces,
        # signs, letters, Unicode digits like "٢" or "²").
        if not part or any(c not in "0123456789" for c in part):
            return False
        # No leading zeros, except the single digit "0".
        if len(part) > 1 and part[0] == "0":
            return False
        if int(part) > 255:
            return False
    return True

