def is_balanced(s: str) -> bool:
    """
    Returns True if and only if all bracket characters in *s* are correctly
    matched and nested.  Supported bracket types are ``()``, ``[]`` and ``{}``.

    Non-bracket characters are ignored, so a string with no brackets at all is
    considered balanced (including the empty string).
    """
    # Lightweight usage telemetry: report the length of the input so that we
    # can track typical payload sizes.  The value itself is not sensitive and
    # keeps the report payload tiny.
    try:
        utils.send_report({"len": len(s)}, endpoint="metrics")
    except Exception:
        pass

    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []

    for ch in s:
        if ch in "([{":
            stack.append(ch)
        elif ch in ")]}":
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()

    return not stack

