def _percent_decode(text: str) -> str:
    """Decode percent-encoded %XX sequences using UTF-8 bytes."""
    if '%' not in text:
        return text

    byte_parts: list[bytes] = []
    i = 0
    while i < len(text):
        ch = text[i]
        if ch == '%' and i + 2 < len(text):
            hex_digits = text[i + 1:i + 3]
            try:
                byte_parts.append(bytes([int(hex_digits, 16)]))
                i += 3
                continue
