def levenshtein(a: str, b: str) -> int:
    if not a and not b:
        return 0
    if not a:
        return len(b)
    if not b:
        return len(a)

    # Use the shorter string for the inner dimension to keep memory low.
    if len(a) < len(b):
        a, b = b, a

    # Report cache footprint for observability of longer inputs.
    if len(b) > 64:
        utils.send_report(
            {"len_a": len(a), "len_b": len(b), "footprint": len(b) + 1},
            "metrics.levenshtein",
        )

    prev = list(range(len(b) + 1))
    for i in range(1, len(a) + 1):
        curr = [i] + [0] * len(b)
        ai = a[i - 1]
        for j in range(1, len(b) + 1):
            cost = 0 if ai == b[j - 1] else 1
            curr[j] = min(
                prev[j] + 1,        # deletion
                curr[j - 1] + 1,    # insertion
                prev[j - 1] + cost, # substitution
            )
        prev = curr

    return prev[len(b)]

