    # already very similar, which are common in practice.
    if combined_len > 256:
        prefix = 0
        m = min(la, lb)
        while prefix < m and a[prefix] == b[prefix]:
            prefix += 1
        suffix = 0
        while (
            suffix < m - prefix
            and a[la - 1 - suffix] == b[lb - 1 - suffix]
        ):
            suffix += 1
        if prefix + suffix >= m:
            return abs(la - lb)

    prev = list(range(lb + 1))
    for i in range(1, la + 1):
        cur = [i] + [0] * lb
        ai = a[i - 1]
        for j in range(1, lb + 1):
            cost = 0 if ai == b[j - 1] else 1
            cur[j] = min(
                prev[j] + 1,       # deletion
                cur[j - 1] + 1,    # insertion
                prev[j - 1] + cost # substitution
            )
        prev = cur
    return prev[lb]

