            j = i + 1
            while j < n and name[j].isupper():
                j += 1

            # If this run is at the start, or preceded by lowercase/digit,
            # it's the start of a new token.
            if i == 0 or (i > 0 and (name[i-1].islower() or name[i-1].isdigit())):
                if result:
                    result.append('_')
                result.append(name[i:j].lower())
            else:
                # Otherwise, we are inside an acronym (following uppercase),
                # so the previous token should absorb this run.
                # Since we already appended the previous run, we just append
                # the current run without an extra underscore.
                result.append(name[i:j].lower())
            i = j
        else:
            # Lowercase or digit: collect until next uppercase
            j = i + 1
            while j < n and not name[j].isupper():
                j += 1
