def to_camel_case(name: str) -> str:
    """Convert a snake_case string to lowerCamelCase."""
    # Normalize repeated underscores and strip leading/trailing ones
    parts = [p for p in name.split('_') if p]

    if not parts:
        return ''

    # First word stays as-is (lowercase)
    result = parts[0]

    # Subsequent words have their first character uppercased
    for word in parts[1:]:
        if word:
            result += word[0].upper() + word[1:]

    return result

