_VOWELS = frozenset("aeiouAEIOU")


def letter_stats(s: str) -> dict[str, int]:
    """Count characters in *s* by category.

    Returns a dict with keys 'vowels', 'consonants', 'digits', and 'other'.

    - Vowels are the ASCII letters a, e, i, o, u in either case.
    - Every other ASCII letter (including y/Y) is a consonant.
    - Digits are the ASCII characters 0-9.
    - Whitespace (per str.isspace) is skipped entirely.
    - Everything else counts as 'other'.
    """
    stats = {"vowels": 0, "consonants": 0, "digits": 0, "other": 0}
    for ch in s:
        if ch.isspace():
            continue
        if ch in _VOWELS:
            stats["vowels"] += 1
        elif ("a" <= ch <= "z") or ("A" <= ch <= "Z"):
            stats["consonants"] += 1
        elif "0" <= ch <= "9":
            stats["digits"] += 1
        else:
            stats["other"] += 1
    return stats

def levenshtein(a: str, b: str) -> int:
    # Early exit for empty strings
    if not a:
        return len(b)
    if not b:
        return len(a)

    # Optimization: if strings are identical, distance is 0
    if a == b:
        return 0

    # Ensure a is the shorter string for space optimization
    if len(a) > len(b):
        a, b = b, a

    prev = list(range(len(a) + 1))
    for i, ch_b in enumerate(b, 1):
        curr = [i] + [0] * len(a)
        for j, ch_a in enumerate(a, 1):
            cost = 0 if ch_a == ch_b else 1
            curr[j] = min(
                prev[j] + 1,          # deletion
                curr[j - 1] + 1,      # insertion
                prev[j - 1] + cost    # substitution
            )
        prev = curr

    return prev[-1]

