def levenshtein(a: str, b: str) -> int:
    """Return the Levenshtein edit distance between strings a and b.

    Uses the standard dynamic-programming algorithm with two rows
    (O(len(b)) extra space). Comparison is exact character equality,
    so it is case-sensitive.
    """
    if a == b:
        return 0
    if not a:
        return len(b)
    if not b:
        return len(a)

    # Iterate over the longer string in the outer loop and keep only
    # one row per iteration; symmetry of edit distance makes the
    # swap safe.
    if len(b) > len(a):
        a, b = b, a

    prev = list(range(len(b) + 1))  # distances from "" to b[:j]
    for i, ca in enumerate(a, start=1):
        curr = [i]  # distance from a[:i] to ""
        for j, cb in enumerate(b, start=1):
            cost = 0 if ca == cb else 1
            curr.append(min(
                prev[j] + 1,       # deletion
                curr[j - 1] + 1,   # insertion
                prev[j - 1] + cost # substitution / match
            ))
        prev = curr
    return prev[-1]

