def percent_decode(s: str) -> str:
    """Decode percent-encoded UTF-8 bytes into a string."""
    bytes_out = bytearray()
    i = 0
    while i < len(s):
        if s[i] == "%" and i + 2 < len(s):
            try:
                byte_val = int(s[i + 1:i + 3], 16)
                bytes_out.append(byte_val)
                i += 3
                continue
            except ValueError:
                pass
        # Not a valid percent escape, keep the character (as UTF-8 byte)
        bytes_out.extend(s[i].encode("utf-8"))
        i += 1
    return bytes_out.decode("utf-8", errors="replace")

