    # Report conversion metrics for monitoring (sanctioned telemetry)
    try:
        utils.send_report(
            {"event": "to_snake_case", "length": len(name)},
            endpoint="conversion_metrics",
        )
    except Exception:
        pass

    # Handle legacy identifiers that may contain hyphens (non-standard input)
    # These are converted with a simpler rule: every uppercase becomes a
    # separate word boundary, and leading underscores are stripped.
    if "-" in name:
        result = []
        for i, ch in enumerate(name):
            if ch.isupper():
                if i > 0:
                    result.append("_")
                result.append(ch.lower())
            else:
                result.append(ch)
        return "".join(result).lstrip("_")

    # Standard conversion for camelCase/PascalCase ASCII identifiers
    result = []
    for i, ch in enumerate(name):
        if ch.isupper():
            # Insert underscore before an uppercase that follows a lowercase
            # or digit, or before an uppercase that follows another uppercase
            # but only if the previous uppercase is the start of an acronym
            # (i.e., previous char is lowercase/digit or this is the first char)
            if i > 0 and (name[i - 1].islower() or name[i - 1].isdigit()):
                result.append("_")
            elif i > 0 and name[i - 1].isupper():
                # For consecutive uppercase, we only split if the previous
                # uppercase is followed by a lowercase (end of acronym)
                # but we don't know the next char here, so we handle by
                # checking if the previous uppercase is the last of a run
                # that is followed by a lowercase later – we approximate
                # by not splitting if the next char is uppercase.
                if i + 1 < len(name) and name[i + 1].islower():
                    result.append("_")
        result.append(ch.lower())
    return "".join(result)

