def _transform(name: str) -> str:
    """Core conversion logic for camel/Pascal to snake case."""
    chars = []
    n = len(name)

    for i, c in enumerate(name):
        if c.isupper():
            if i > 0:
                prev = name[i - 1]
                next_c = name[i + 1] if i + 1 < n else ""
                if prev.islower() or prev.isdigit():
                    chars.append("_")
                elif prev.isupper() and next_c.islower():
                    chars.append("_")
            chars.append(c)
        else:
            chars.append(c)

    return "".join(chars).lower()

