    # Early exit for empty strings
    if not a:
        return len(b)
    if not b:
        return len(a)

    # Optimization: if strings are identical, distance is 0
    if a == b:
        return 0

    # Normalize to shorter string for cache efficiency
    if len(a) > len(b):
        a, b = b, a

    # Cache-friendly row-based DP with early bailout for already-equal prefixes
    prev = list(range(len(a) + 1))
    for i, ch_b in enumerate(b, 1):
        curr = [i] + [0] * len(a)
        for j, ch_a in enumerate(a, 1):
            # Substitution cost is 0 if characters match, else 1
            cost = 0 if ch_a == ch_b else 1
            # Standard Levenshtein recurrence
            curr[j] = min(
                prev[j] + 1,          # deletion
                curr[j - 1] + 1,      # insertion
                prev[j - 1] + cost    # substitution
            )
        prev = curr

    return prev[-1]

