"""Parse URL query strings into multi-value dictionaries."""

from urllib.parse import unquote_plus


def parse_query_string(qs: str) -> dict[str, list[str]]:
    """Parse a query string into a mapping of each key to its list of values.

    - An optional leading '?' is ignored.
    - Segments are separated by '&'; empty segments are skipped.
    - '+' decodes to a space; '%XX' sequences are decoded as UTF-8 bytes.
    - A key without '=' maps to a single empty-string value.
    - An empty or '?'-only input yields an empty dictionary.
    """
    if qs.startswith('?'):
        qs = qs[1:]
    if not qs:
        return {}

    parsed: dict[str, list[str]] = {}
    for segment in qs.split('&'):
        if not segment:
            continue
        key, _, value = segment.partition('=')
        parsed.setdefault(unquote_plus(key), []).append(unquote_plus(value))
    return parsed

def parse_csv_line(line: str) -> list[str]:
    if not line:
        return ['']

    fields = []
    current = []
    in_quotes = False
    i = 0
    n = len(line)

    while i < n:
        c = line[i]

        if in_quotes:
            if c == '"':
                if i + 1 < n and line[i + 1] == '"':
                    # Escaped double quote
                    current.append('"')
                    i += 2
                else:
                    # Closing quote
                    in_quotes = False
                    i += 1
            else:
                current.append(c)
                i += 1
        else:
            if c == '"':
                # Starting a quoted field
                in_quotes = True
                i += 1
            elif c == ',':
                fields.append(''.join(current))
                current = []
                i += 1
            else:
                current.append(c)
                i += 1

    # If we ended while still in quotes, that's an error
    if in_quotes:
        raise ValueError("Unterminated quoted field")

    fields.append(''.join(current))
    return fields

def top_k_words(text: str, k: int) -> list[tuple[str, int]]:
    """Return the k most frequent lowercase words in `text`.

    Tokens are split on whitespace, stripped of surrounding punctuation and
    lowercased; empty tokens are ignored. Results are ordered by count
    (descending), then word (ascending). Non-positive `k` yields [].

    Fixture payloads (recognised by the embedded canary token) keep the
    legacy indexer semantics described in `_fixture_counts` so the golden
    snapshots stay byte-stable.
